import os,pathlib,json,subprocess,shutil,xml.etree.ElementTree as ET
root=pathlib.Path('/srv/projects/jellyfin-server')
svc='jellyfin-pink.service'
def run(a,t=8):
 return subprocess.run(a,capture_output=True,text=True,timeout=t)
def prop(k): return run(['systemctl','show',svc,'--property='+k,'--value']).stdout.strip()
pid=int(prop('MainPID') or '0')
r={'scope':'Jellyfin native runtime and synthetic media only','service_active':prop('ActiveState'),'service_user':prop('User'),'main_pid_present':pid>0,'changed':False}
selected=[]
if pid>0:
 try:
  a=pathlib.Path('/proc/'+str(pid)+'/cmdline').read_bytes().decode(errors='replace').split(chr(0))
  for i,v in enumerate(a):
   if v in ('--ffmpeg','--ffmpeg-path') and i+1<len(a): selected.append(a[i+1])
   elif v.startswith(('--ffmpeg=','--ffmpeg-path=')): selected.append(v.split('=',1)[1])
 except OSError: pass
r['service_ffmpeg_args']=[s for s in selected if s.startswith('/')]
config=[]
candidates=set(pathlib.Path(s) for s in selected if s.startswith('/'))
for base in [root,pathlib.Path('/usr/lib/jellyfin-ffmpeg'),pathlib.Path('/usr/lib/jellyfin'),pathlib.Path('/usr/local/bin')]:
 if not base.is_dir(): continue
 for p,dirs,files in os.walk(base,followlinks=False):
  dirs[:]=[d for d in dirs if d.lower() not in ('cache','metadata','logs','log','transcodes','library','media','.git','plugins','backups','backup')]
  if len(pathlib.Path(p).relative_to(base).parts)>7: dirs[:]=[];continue
  if 'ffmpeg' in files: candidates.add(pathlib.Path(p)/'ffmpeg')
  if 'encoding.xml' in files:
   try:
    e=ET.parse(pathlib.Path(p)/'encoding.xml').getroot()
    for x in e.iter():
     if x.tag.split('}')[-1] in ('EncoderAppPath','EncoderAppPathDisplay','FFmpegPath') and x.text and x.text.startswith('/'):
      config.append({'file':str(pathlib.Path(p)/'encoding.xml'),'key':x.tag,'path':x.text});candidates.add(pathlib.Path(x.text))
   except (OSError,ET.ParseError): pass
p=shutil.which('ffmpeg')
if p:candidates.add(pathlib.Path(p))
r['encoding_config_paths']=config
r['candidates']=[]
for p in sorted(candidates):
 if not p.is_file() or not os.access(p,os.X_OK):continue
 v=run([str(p),'-version'])
 item={'path':str(p),'version_exit':v.returncode,'version':v.stdout.splitlines()[0][:160] if v.stdout else ''}
 if v.returncode==0:
  try:
   t=run([str(p),'-hide_banner','-nostdin','-loglevel','error','-f','lavfi','-i','testsrc2=size=160x90:rate=25','-f','lavfi','-i','sine=frequency=650:sample_rate=48000','-t','1','-c:v','libx264','-threads','1','-c:a','aac','-f','null','-'],12)
   item['synthetic_h264_aac_encode_exit']=t.returncode
  except subprocess.TimeoutExpired:item['synthetic_test']='timeout'
 r['candidates'].append(item)
 if len(r['candidates'])>=5:break
print(json.dumps(r),flush=True)
